using System.Text;
using FluentAssertions;
using Kiln.Audio;
using Kiln.Audio.Entropy;
using Kiln.Audio.Silk;
using Kiln.Audio.Tests.Oracle;
using Xunit.Abstractions;

namespace Kiln.Audio.Tests.Silk;

/// <summary>
/// Checks SILK synthesis bit-for-bit against libopus decoded at the internal SILK rate.
/// </summary>
/// <remarks>
/// <para>
/// Each stream is generated by encoding the reference test-vector audio with <c>opus_demo -e
/// voip</c> forced to one bandwidth, frame size, channel count and constant bitrate, so every
/// packet is SILK-only. The same packets are then decoded twice: by <c>opus_demo -d</c> at the
/// internal rate (8, 12 or 16 kHz), and by <see cref="SilkDecoder"/> + <see cref="SilkSynthesis"/>.
/// </para>
/// <para>
/// libopus always runs its internal-rate resampler, even when the requested rate equals the
/// internal rate, and the copy path delays the signal by a fixed number of samples. The delay is
/// <c>DelaySamples8k</c> (and so on) below; the test finds it by exact search and asserts the
/// same value for every stream at a rate. After alignment, every sample must be identical.
/// </para>
/// </remarks>
public class SilkPcmOracleTests
{
    /// <summary>
    /// Delay of libopus's internal-rate copy resampler, in samples per channel, measured by exact
    /// search over the whole stream. Mono is delayed by one sample more than stereo because the
    /// mono path buffers the two-sample mid history before the resampler (dec_API.c).
    /// </summary>
    /// <remarks>
    /// 8 kHz: mono 5, stereo 4; 12 kHz: mono 10, stereo 9; 16 kHz: mono 13, stereo 12.
    /// </remarks>
    private static int ExpectedDelay(int rate, int channels) => channels == 2
        ? rate switch { 8000 => 4, 12000 => 9, _ => 12 }
        : rate switch { 8000 => 5, 12000 => 10, _ => 13 };

    private readonly ITestOutputHelper _output;

    public SilkPcmOracleTests(ITestOutputHelper output)
    {
        _output = output;
    }

    [Fact]
    public void Silk_only_streams_are_bit_exact_with_libopus()
    {
        if (!OracleTestSupport.OracleAvailable())
        {
            _output.WriteLine("libopus oracle not available; skipping.");
            return;
        }

        var report = new StringBuilder();
        int bitExact = 0;
        int total = 0;
        int midOnlyTotal = 0;
        var delays = new Dictionary<(int Rate, int Channels), List<(int Delay, string Name)>>();

        foreach (BandwidthCase bandwidth in BandwidthCases)
        {
            short[] stereo = Pcm16.Read(TestVectors.DecPath(
                bandwidth.Bandwidth == OpusBandwidth.Narrowband ? 2 : 3));
            short[] mono = Downmix(stereo);

            foreach (int frameSizeMs in FrameSizes)
            {
                foreach (bool isStereo in new[] { false, true })
                {
                    total++;
                    string name = FormattableString.Invariant(
                        $"{bandwidth.Bandwidth} {frameSizeMs}ms {(isStereo ? "stereo" : "mono")}");
                    short[] input = isStereo ? stereo : mono;
                    int channels = isStereo ? 2 : 1;
                    int requestedBitrate = isStereo ? 24000 : 12000;

                    byte[] bitFile = EncodeSilkOnly(
                        input, channels, requestedBitrate, bandwidth.Name, frameSizeMs);

                    short[] reference = DecodeWithOracle(bitFile, bandwidth.InternalRate, channels);
                    (short[] ours, int packetCount, int finalRangeMatches, int midOnlySilkFrames) =
                        DecodeWithOurs(bitFile, bandwidth.InternalRate, channels);
                    midOnlyTotal += midOnlySilkFrames;

                    finalRangeMatches.Should().Be(
                        packetCount, "{0}: every packet's final range must match", name);
                    ours.Length.Should().Be(reference.Length, "{0}: sample count", name);

                    int delay = FindDelay(ours, reference);
                    delays.TryAdd((bandwidth.InternalRate, channels), []);
                    delays[(bandwidth.InternalRate, channels)].Add((delay, name));

                    int firstMismatch = FirstMismatch(ours, reference, delay);
                    if (firstMismatch < 0)
                    {
                        bitExact++;
                        report.AppendLine($"{name}: exact at delay {delay}");
                    }
                    else
                    {
                        int frameLength = frameSizeMs * bandwidth.InternalRate / 1000;
                        int subframeLength = 5 * (bandwidth.InternalRate / 1000);
                        int frame = firstMismatch / frameLength;
                        int subframe = (firstMismatch % frameLength) / subframeLength;
                        int maxDiff = MaxAbsDifference(ours, reference, delay);
                        report.AppendLine(
                            $"MISMATCH {name}: delay {delay}, first sample {firstMismatch} " +
                            $"(frame {frame}, subframe {subframe}), max abs diff {maxDiff}");
                    }
                }
            }
        }

        foreach (((int rate, int channels), List<(int Delay, string Name)> values) in delays)
        {
            int expected = ExpectedDelay(rate, channels) * channels;
            foreach ((int delay, string name) in values)
            {
                report.AppendLine(
                    $"rate {rate}, {channels} ch: {name} interleaved delay {delay} " +
                    $"(per channel {delay / channels})");
            }

            foreach ((int delay, string name) in values)
            {
                delay.Should().Be(
                    expected,
                    "{0}: the interleaved delay must be {1} for every {2}-channel stream at {3} Hz\n{4}",
                    name,
                    expected,
                    channels,
                    rate,
                    report);
            }
        }

        _output.WriteLine(report.ToString());
        _output.WriteLine("Mid-only SILK frames exercised: {0}.", midOnlyTotal);
        bitExact.Should().Be(total, "{0}/{1} streams are bit-exact after alignment:\n{2}", bitExact, total, report);
    }

    [Fact]
    public void Mid_only_stereo_frames_are_exercised()
    {
        // The RFC 8251 SILK stereo vectors code side frames as mid-only, which keeps the
        // mid-only unmixing path covered independently of the generated streams.
        var frames = new Range[OpusPacket.MaxFrames];
        var decoder = new SilkDecoder();
        var result = new SilkFrameResult();
        int midOnly = 0;

        foreach (int vector in new[] { 3, 4 })
        {
            foreach ((byte[] packet, _) in OpusBitFile.Read(TestVectors.BitPath(vector)))
            {
                OpusToc toc = OpusToc.Parse(packet[0]);
                if (toc.Mode != OpusMode.Silk || !toc.IsStereo)
                {
                    continue;
                }

                OpusStatus status = OpusPacket.TryParse(packet, frames, out int frameCount, out _, out _);
                status.Should().Be(OpusStatus.Ok);
                int rate = toc.Bandwidth == OpusBandwidth.Mediumband ? 12000 : 16000;
                int durationMs = toc.FrameDuration switch
                {
                    OpusFrameDuration.Ms10 => 10,
                    OpusFrameDuration.Ms20 => 20,
                    OpusFrameDuration.Ms40 => 40,
                    _ => 60,
                };

                for (int frameIndex = 0; frameIndex < frameCount; frameIndex++)
                {
                    var dec = new RangeDecoder(packet.AsSpan(frames[frameIndex]));
                    decoder.DecodeFrame(ref dec, rate, 2, durationMs, result);
                    for (int silkFrame = 0; silkFrame < result.SilkFrameCount; silkFrame++)
                    {
                        if (!result.IsRegularCoded(silkFrame, 1))
                        {
                            midOnly++;
                        }
                    }
                }
            }
        }

        _output.WriteLine("Mid-only SILK frames in testvector03/04: {0}.", midOnly);
        midOnly.Should().BeGreaterThan(0);
    }

    private static readonly BandwidthCase[] BandwidthCases =
    [
        new("NB", 8000, OpusBandwidth.Narrowband),
        new("MB", 12000, OpusBandwidth.Mediumband),
        new("WB", 16000, OpusBandwidth.Wideband),
    ];

    private static readonly int[] FrameSizes = [10, 20, 40, 60];

    private readonly record struct BandwidthCase(string Name, int InternalRate, OpusBandwidth Bandwidth);

    /// <summary>
    /// Encodes a stream whose every packet is SILK-only and has the requested channel count.
    /// </summary>
    /// <remarks>
    /// libopus chooses mono or stereo from the equivalent 20 ms rate
    /// (<c>opus_encoder.c</c>, <c>stereo_threshold</c>). At 24 kbps and a 10 ms frame size its
    /// equivalent rate falls below the threshold and it codes stereo input as mono, so the
    /// bitrate is raised until every packet is stereo. The bitrate actually used is reported.
    /// </remarks>
    private static byte[] EncodeSilkOnly(
        short[] input, int channels, int requestedBitrate, string bandwidth, int frameSizeMs)
    {
        int[] bitrates = channels == 2 ? [requestedBitrate, 32000, 40000] : [requestedBitrate];
        foreach (int bitrate in bitrates)
        {
            byte[] bitFile = LibOpusOracle.Encode(
                input,
                48000,
                channels,
                bitrate,
                ["-bandwidth", bandwidth, "-framesize", frameSizeMs.ToString(), "-cbr"]);
            if (IsSilkOnly(bitFile, channels))
            {
                return bitFile;
            }
        }

        throw new InvalidOperationException(
            FormattableString.Invariant(
                $"No SILK-only {channels}-channel stream at {bandwidth}, {frameSizeMs} ms."));
    }

    private static bool IsSilkOnly(byte[] bitFile, int channels)
    {
        string path = Path.Combine(
            Path.GetTempPath(), FormattableString.Invariant($"kiln-silk-{Guid.NewGuid():N}.bit"));
        try
        {
            File.WriteAllBytes(path, bitFile);
            foreach ((byte[] packet, _) in OpusBitFile.Read(path))
            {
                OpusToc toc = OpusToc.Parse(packet[0]);
                if (toc.Mode != OpusMode.Silk || toc.IsStereo != (channels == 2))
                {
                    return false;
                }
            }

            return true;
        }
        finally
        {
            File.Delete(path);
        }
    }

    private static short[] Downmix(short[] stereo)
    {
        var mono = new short[stereo.Length / 2];
        for (int i = 0; i < mono.Length; i++)
        {
            mono[i] = (short)((stereo[2 * i] + stereo[(2 * i) + 1]) / 2);
        }

        return mono;
    }

    private static short[] DecodeWithOracle(byte[] bitFile, int rate, int channels)
    {
        string path = Path.Combine(
            Path.GetTempPath(), FormattableString.Invariant($"kiln-silk-{Guid.NewGuid():N}.bit"));
        try
        {
            File.WriteAllBytes(path, bitFile);
            return LibOpusOracle.Decode(path, rate, channels);
        }
        finally
        {
            File.Delete(path);
        }
    }

    private static (short[] Pcm, int PacketCount, int FinalRangeMatches, int MidOnlySilkFrames) DecodeWithOurs(
        byte[] bitFile, int rate, int channels)
    {
        string path = Path.Combine(
            Path.GetTempPath(), FormattableString.Invariant($"kiln-silk-{Guid.NewGuid():N}.bit"));
        var pcm = new List<short>();
        var frames = new Range[OpusPacket.MaxFrames];
        var decoder = new SilkDecoder();
        var synthesis = new SilkSynthesis();
        var result = new SilkFrameResult();
        int packetCount = 0;
        int finalRangeMatches = 0;
        int midOnlySilkFrames = 0;
        try
        {
            File.WriteAllBytes(path, bitFile);
            foreach ((byte[] packet, uint finalRange) in OpusBitFile.Read(path))
            {
                packetCount++;
                OpusToc toc = OpusToc.Parse(packet[0]);
                toc.Mode.Should().Be(OpusMode.Silk, "packet {0} must be SILK-only", packetCount);
                toc.IsStereo.Should().Be(channels == 2, "packet {0} channel count", packetCount);

                OpusStatus status = OpusPacket.TryParse(
                    packet, frames, out int frameCount, out OpusToc parsed, out _);
                status.Should().Be(OpusStatus.Ok, "packet {0}", packetCount);

                int durationMs = parsed.FrameDuration switch
                {
                    OpusFrameDuration.Ms10 => 10,
                    OpusFrameDuration.Ms20 => 20,
                    OpusFrameDuration.Ms40 => 40,
                    _ => 60,
                };

                for (int frameIndex = 0; frameIndex < frameCount; frameIndex++)
                {
                    Range frameRange = frames[frameIndex];
                    var dec = new RangeDecoder(packet.AsSpan(frameRange));
                    decoder.DecodeFrame(ref dec, rate, channels, durationMs, result);
                    for (int silkFrame = 0; silkFrame < result.SilkFrameCount; silkFrame++)
                    {
                        if (channels == 2 && !result.IsRegularCoded(silkFrame, 1))
                        {
                            midOnlySilkFrames++;
                        }
                    }

                    if (frameIndex == frameCount - 1)
                    {
                        if (dec.Rng == finalRange)
                        {
                            finalRangeMatches++;
                        }
                    }

                    int samplesPerChannel = durationMs * rate / 1000;
                    var pcmFrame = new short[samplesPerChannel * channels];
                    synthesis.Synthesize(result, pcmFrame);
                    pcm.AddRange(pcmFrame);
                }
            }
        }
        finally
        {
            File.Delete(path);
        }

        return (pcm.ToArray(), packetCount, finalRangeMatches, midOnlySilkFrames);
    }

    private static int FindDelay(short[] ours, short[] reference)
    {
        int bestDelay = 0;
        int bestPrefix = -1;
        for (int delay = 0; delay <= 64; delay++)
        {
            int n = 0;
            while (n < ours.Length - delay && ours[n] == reference[n + delay])
            {
                n++;
            }

            if (n > bestPrefix)
            {
                bestPrefix = n;
                bestDelay = delay;
            }
        }

        return bestDelay;
    }

    private static int FirstMismatch(short[] ours, short[] reference, int delay)
    {
        for (int n = 0; n < ours.Length - delay; n++)
        {
            if (ours[n] != reference[n + delay])
            {
                return n;
            }
        }

        return -1;
    }

    private static int MaxAbsDifference(short[] ours, short[] reference, int delay)
    {
        int max = 0;
        for (int n = 0; n < ours.Length - delay; n++)
        {
            int difference = Math.Abs(ours[n] - reference[n + delay]);
            if (difference > max)
            {
                max = difference;
            }
        }

        return max;
    }
}
